const magentoItems = $items("Split Out");
const sheetItems = $items("Get_processed_velos");

// On crée une "map" pour chercher les prix du Sheet par SKU très rapidement
const sheetMap = {};
sheetItems.forEach(item => {
  if (item.json.SKU) {
    sheetMap[item.json.SKU] = {
      prix: parseFloat(item.json.Prix),
      nom: item.json.Modèle
    };
  }
});

const results = [];

for (const item of magentoItems) {
  const m = item.json;
  const sku = m.sku;
  const prixActuel = parseFloat(m.price);
  const existant = sheetMap[sku];

  if (!existant) {
    // Cas 1 : Le vélo n'est pas dans le Sheet
    results.push({ json: { ...m, action: 'AJOUTER', raison: 'Nouveau vélo' } });
  } else if (existant.prix !== prixActuel) {
    // Cas 2 : Le prix a changé
    results.push({ 
      json: { 
        ...m, 
        action: 'UPDATE_PRIX', 
        ancien_prix: existant.prix, 
        nouveau_prix: prixActuel,
        raison: `Le prix a changé : ${existant.prix}€ -> ${prixActuel}€`
      } 
    });
  }
}

return results;

// Récupère les dossiers déjà traités depuis le Google Sheet
const sheetItems = $items("Get_Processed_velos", 0);
const processedNames = sheetItems
  .map(i => i.json.Modele?.trim().toLowerCase())
  .filter(v => v && v.length > 0);

// Récupère les dossiers depuis Google Drive
const driveItems = $items("Split_out", 0);
const newFolders = driveItems.filter(i => {
  const name = (i.json.name || "").trim().toLowerCase();
  return name && !processedNames.includes(name);
});

// Retourne uniquement les nouveaux dossiers
return newFolders.map(i => ({
  json: {
    name: i.json.name,
    id: i.json.id
  }
}));
